#include <iostream>
using namespace std;

int main() {
    // Variables can change!
    int score = 0;
    cout << "Start: " << score << endl;

    score = 10;
    cout << "After setting to 10: " << score << endl;

    score = score + 5;
    cout << "After adding 5: " << score << endl;

    score = score * 2;
    cout << "After doubling: " << score << endl;

    // The = vs == difference
    int x = 42;           // Assignment: put 42 in x

    if (x == 42) {        // Comparison: is x equal to 42?
        cout << "x is 42!" << endl;
    }

    return 0;
}

