#include <iostream>
using namespace std;

int main() {
    int lives = 3;
    cout << "Game Start - Lives: " << lives << endl;

    lives = lives - 1;  // Lost a life
    cout << "After hit - Lives: " << lives << endl;

    lives = lives - 1;  // Lost another life
    cout << "After hit - Lives: " << lives << endl;

    lives = lives + 2;  // Found extra lives!
    cout << "Found bonus - Lives: " << lives << endl;

    // Shortcut operators
    int score = 100;
    score += 50;   // Same as: score = score + 50
    cout << "Score after += 50: " << score << endl;

    score -= 25;   // Same as: score = score - 25
    cout << "Score after -= 25: " << score << endl;

    score *= 2;    // Same as: score = score * 2
    cout << "Score after *= 2: " << score << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int x = 10;  // ASSIGNMENT: put 10 in x

    cout << "x = " << x << endl;

    // COMPARISON: check if x equals 10
    if (x == 10) {
        cout << "x is 10! (comparison works)" << endl;
    }

    // COMPARISON: check if x equals 20
    if (x == 20) {
        cout << "This won't print" << endl;
    } else {
        cout << "x is NOT 20 (comparison works)" << endl;
    }

    // Reassignment
    x = 20;  // ASSIGNMENT: now x holds 20
    cout << "After x = 20, x is: " << x << endl;

    return 0;
}

